# Let's construct a graph that satisfies constraints.
# We'll use bipartite approach.

vertices = list(range(16))
fixed_edges = [(0,3), (0,8), (1,7), (1,10), (1,14)]

# Assign bipartition based on fixed edges: we need to ensure no edge within same part.
# Let's use a simple 2-coloring of the fixed graph.
color = {}
# Start BFS on each component
from collections import deque
adj = {v: set() for v in vertices}
for u,v in fixed_edges:
    adj[u].add(v)
    adj[v].add(u)

for v in vertices:
    if v not in color:
        color[v] = 0
        q = deque([v])
        while q:
            u = q.popleft()
            for w in adj[u]:
                if w not in color:
                    color[w] = 1 - color[u]
                    q.append(w)
                elif color[w] == color[u]:
                    raise Exception("Not bipartite")
print("Colors:", color)

# Let's double-check everything
edges = [(0, 3), (0, 8), (1, 7), (1, 10), (1, 14), (2, 3), (4, 3), (5, 3), (6, 3), (9, 3), (11, 3), (12, 3), (13, 3), (15, 3)]

# Build adjacency
adj = {i: set() for i in range(16)}
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

# Check degrees
for v in range(16):
    print(f"Vertex {v}: degree {len(adj[v])}, neighbors {sorted(adj[v])}")

# Check fixed edges
fixed = [(1,7), (1,10), (0,8), (0,3), (1,14)]
for u,v in fixed:
    assert v in adj[u], f"Missing ({u},{v})"
print("All fixed edges present")

# Max clique: check all triples
import itertools
for combo in itertools.combinations(range(16), 3):
    if all(v2 in adj[v1] for v1 in combo for v2 in combo if v1 < v2):
        print(f"Clique of size 3: {combo}")
        break
else:
    print("No clique of size 3")

# Chromatic number: 2-coloring
color = {}
def dfs(v, c):
    color[v] = c
    for u in adj[v]:
        if u in color:
            if color[u] == c:
                return False
        else:
            if not dfs(u, 1-c):
                return False
    return True

for v in range(16):
    if v not in color:
        if not dfs(v, 0):
            print("Not bipartite")
            break
else:
    print("Graph is bipartite (2-colorable)")
    print("Colors:", color)
